"""Assemble the PUBLIC code repository from this private repository (CLAUDE.md: the public tree is generated by a
script, never edited by hand; participant-level data are not included).

What it does
  1. classifies every path that was ever tracked in the private history as KEEP / DROP (rules below; the manifest
     with one line per file is written next to the output directory);
  2. clones the private repository (fresh clone, `--no-local`) into --out and removes the DROP paths from EVERY
     commit with git-filter-repo (history is otherwise preserved: messages, dates, author, lightweight tags);
     the old -> new commit map is written next to the output directory;
  3. renames the branch to `main`, adds the release files from public_repo/ (README.md with the commit placeholders
     filled, LICENSE, LICENSE-docs, CITATION.cff, RELEASE_STEPS.md, .gitignore) in one final commit;
  4. checks (unless --no-check): grep for private strings, size limits, a clone -> `uv sync --frozen` ->
     `python -I scripts/88_paper_numbers.py` round trip that must reproduce paper/numbers.md byte for byte, the unit
     test in scripts/tests/, and a clean `git status`.

Usage (from the private repository root; git-filter-repo is only needed for this script):
  uv run --with git-filter-repo python scripts/91_build_public_repo.py [--out ~/public/collective-individuality-transfer]
        [--force] [--no-check] [--tmp DIR] [--allow-dirty]
"""
import argparse, fnmatch, json, os, re, shutil, subprocess, sys, tempfile, time
from pathlib import Path

SRC = Path(__file__).resolve().parents[1]
PUB = SRC / 'public_repo'
AUTHOR = ['-c', 'user.name=Hiroshi Higashi', '-c', 'user.email=hgshrs@kansai-u.ac.jp']
TRAILER = ('Co-Authored-By: Claude Fable 5.1 <noreply@anthropic.com>\n'
           'Claude-Session: https://claude.ai/code/session_01TfjJPQUribrY6MM9krPaUT')

# ---------------------------------------------------------------- classification rules (order matters: first match wins)
DROP_DIRS = {  # whole directories
    'refs': 'third-party PDFs (copyright)',
    'data': 'participant-level data (raw downloads and derived tables); regenerated by scripts/00-04, 61-63, 70-71',
    'external': 'third-party code and data (Chirkov OSF code, Wu and Hawkins repositories); not redistributed',
    'runs': 'model checkpoints and brms fits', 'logs': 'logs',
    'public_repo': 'sources of the release files (added by the final public commit instead)',
}
DROP_FILES = {  # exact paths
    'reports/HANDOVER.md': 'internal hand-over notes (Japanese; contains local paths)',
    'paper/numbers.md': 'manuscript drafting material; regenerated by scripts/88',
    'paper/figure_legends.md': 'manuscript drafting material',
    'paper/WRITING_BRIEF.md': 'manuscript drafting material (writing instructions)',
}
DROP_GLOBS = [  # (glob, reason, zenodo?)  zenodo = candidate for the Zenodo artefact archive
    ('reports/summary_undergrad_*.html', 'internal lay summary (Japanese)', False),
    ('paper/figures/*.tif', '600 dpi submission TIFF (Zenodo archive); PDF kept', True),
    ('paper/figures/build/*', 'LaTeX build files', False),
    # participant-level result files (one row per participant or per pair of participants of a public dataset)
    ('results/phase1/cross_individual_pairs_*.csv', 'pair-level transfer errors (participant pairs)', True),
    ('results/phase1/ah2_linear_z_pairs.csv', 'pair-level transfer errors (participant pairs)', True),
    ('results/phase1/pred_*.csv', 'per-participant predicted teacher weights', True),
    ('results/phase1/z_*.csv', 'per-participant z', True),
    ('results/phase1/z_individual.npz', 'per-participant z', True),
    ('results/phase1/sim_z_*.csv', 'per-simulated-agent z', True),
    ('results/phase1/nll_b_phase1_b_z4_eb.csv', 'per-participant likelihoods', True),
    ('results/phase2/*oof_predictions.csv', 'per-participant out-of-fold predictions', True),
    ('results/phase2/z_planB_pca4_oof.csv', 'per-participant z', True),
    ('results/phase2/z_planB_cnn_seed*.csv', 'per-participant z', True),
    ('results/phase3/policy_params_*.csv', 'per-participant fitted policy parameters', True),
    ('results/phase3/d2_z.csv', 'per-participant z', True),
    ('results/phase3/d2_predictive.csv', 'per-participant likelihoods', True),
    ('results/phase3/policy_vs_linear_predictive.csv', 'per-participant likelihoods', True),
    ('results/diagnostics/composition_individuals.csv', 'per-participant table', True),
    ('results/hawkins2023/teacher_weights.csv', 'per-participant teacher weights', True),
    ('results/hawkins2023/z_first_half.csv', 'per-participant z', True),
    ('results/wu2025/choice_weights.csv', 'per-participant choice-model weights', True),
    ('results/wu2025/z_solo_pca4.csv', 'per-participant z', True),
    ('results/wu2025/sim_mobility_params.csv', 'per-participant mobility parameters', True),
    ('results/wu2025/stan_vID_*.csv', 'per-participant posterior means extracted from the published Stan fits', True),
    ('results/phase0/audit_*_per_participant.csv', 'per-participant audit rows (regenerated by scripts/01)', False),
    # raw seed x group simulation outputs
    ('results/*/sim_runs*.parquet', 'raw seed x group simulation runs (Zenodo archive); seed-mean evaluations kept', True),
    ('results/phase3/social_rules_runs.parquet', 'raw seed x group simulation runs (Zenodo archive)', True),
    ('results/diagnostics/abm_het_real_groups.csv', 'raw seed x group simulation runs (Zenodo archive)', True),
    # per-variant diagnostic figures of the learning-rate sweeps (their summary CSV/JSON files are kept)
    ('results/phase1/fig_*_lr*', 'learning-rate-sweep variant figure (summary tables kept)', False),
    ('results/phase1/fig_*_ep*k_*', 'learning-rate-sweep variant figure (summary tables kept)', False),
    ('results/phase1/fig_*_tuned*', 'learning-rate-sweep variant figure (summary tables kept)', False),
]
CHECK_PATTERNS = [('/home/', r'/home/'), ('/Users/', r'/Users/'), ('/mnt/', r'/mnt/'),
                  ('email', r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}'), ('token', r'(?i)\btoken'),
                  ('secret', r'(?i)\bsecret'), ('api_key', r'(?i)api[_-]?key'), ('prolific', r'(?i)prolific'), ('worker', r'(?i)\bworker')]
ALLOWED_EMAILS = {'hgshrs@kansai-u.ac.jp', 'noreply@anthropic.com'}
MAX_TOTAL, MAX_FILE = 100 * 2**20, 10 * 2**20


def classify(path):
    """-> (drop: bool, reason: str, zenodo: bool)"""
    top = path.split('/')[0]
    if top in DROP_DIRS: return True, DROP_DIRS[top], False
    if path in DROP_FILES: return True, DROP_FILES[path], False
    for g, reason, z in DROP_GLOBS:
        if fnmatch.fnmatchcase(path, g): return True, reason, z
    return False, '', False


def git(args, cwd, check=True, capture=True):
    r = subprocess.run(['git', *args], cwd=cwd, text=True, capture_output=capture)
    if check and r.returncode: raise SystemExit(f'git {" ".join(args)} failed in {cwd}:\n{r.stderr}')
    return r.stdout if capture else ''


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--out', default=os.path.expanduser('~/public/collective-individuality-transfer'))
    ap.add_argument('--force', action='store_true', help='delete an existing --out directory first')
    ap.add_argument('--no-check', action='store_true'); ap.add_argument('--allow-dirty', action='store_true')
    ap.add_argument('--tmp', default=None, help='directory for the clone-and-run check (default: system temp)')
    a = ap.parse_args(); OUT = Path(a.out).resolve(); t0 = time.time()

    # ---------------------------------------------------------------- 0. preconditions
    dirty = [l for l in git(['status', '--porcelain'], SRC).splitlines() if not l.startswith('??')]
    if dirty and not a.allow_dirty: raise SystemExit('private repository has uncommitted tracked changes; commit first (or --allow-dirty):\n' + '\n'.join(dirty))
    try: import git_filter_repo  # noqa: F401
    except ImportError: raise SystemExit('git-filter-repo missing: run with `uv run --with git-filter-repo python scripts/91_build_public_repo.py`')
    head = git(['rev-parse', 'HEAD'], SRC).strip(); branch = git(['rev-parse', '--abbrev-ref', 'HEAD'], SRC).strip()
    first = git(['rev-list', '--max-parents=0', 'HEAD'], SRC).split()[-1]

    # ---------------------------------------------------------------- 1. classify every path ever tracked
    now = set(git(['ls-files'], SRC).splitlines())
    ever = set(git(['log', '--all', '--name-only', '--format='], SRC).splitlines()) - {''}
    ever |= now
    drop, keep, manifest = [], [], []
    for p in sorted(ever):
        d, reason, z = classify(p); size = (SRC / p).stat().st_size if p in now and (SRC / p).exists() else -1
        (drop if d else keep).append(p)
        manifest.append((p, size, 'drop' if d else 'keep', reason, 'zenodo' if z else '', '' if p in now else 'history-only'))
    keep_now = [p for p in keep if p in now]
    print(f'paths ever tracked: {len(ever)}; current: {len(now)}; keep: {len(keep_now)} ({sum(s for p, s, *_ in manifest if p in keep_now) / 2**20:.1f} MB); drop: {len(drop)}')
    OUT.parent.mkdir(parents=True, exist_ok=True)
    man_path = OUT.parent / (OUT.name + '_manifest.tsv')
    man_path.write_text('path\tbytes\tstatus\treason\tzenodo\tnote\n' + '\n'.join('\t'.join(map(str, m)) for m in manifest) + '\n')

    # ---------------------------------------------------------------- 2. fresh clone + filter-repo
    if OUT.exists():
        if not a.force: raise SystemExit(f'{OUT} exists; use --force to delete and rebuild it')
        shutil.rmtree(OUT)
    git(['clone', '--no-local', '--quiet', str(SRC), str(OUT)], SRC)
    listfile = OUT.parent / (OUT.name + '_drop_paths.txt')
    listfile.write_text('\n'.join(list(DROP_DIRS) + drop) + '\n')  # literal paths; a directory name drops the whole directory
    r = subprocess.run([sys.executable, '-m', 'git_filter_repo', '--invert-paths', '--paths-from-file', str(listfile), '--quiet'], cwd=OUT, text=True, capture_output=True)
    if r.returncode: raise SystemExit('git filter-repo failed:\n' + r.stdout + r.stderr)
    cmap = {}
    for line in (OUT / '.git/filter-repo/commit-map').read_text().splitlines()[1:]:
        o, n = line.split(); cmap[o] = n
    if branch != 'main': git(['branch', '-m', branch, 'main'], OUT)
    pub_first = cmap.get(first, '?'); pub_last_analysis = cmap.get(head, '?')
    first_date = git(['log', '-1', '--format=%ad', '--date=short', first], SRC).strip()
    tree = set(git(['ls-files'], OUT).splitlines())
    missing, extra = sorted(set(keep_now) - tree), sorted(tree - set(keep_now))
    if missing or extra: raise SystemExit(f'tree mismatch after filtering: missing {missing[:5]} extra {extra[:5]}')
    n_commits = int(git(['rev-list', '--count', 'HEAD'], OUT))
    print(f'history rewritten: {n_commits} commits (private: {int(git(["rev-list", "--count", "HEAD"], SRC))}); first {first[:7]} -> {pub_first[:7]}; HEAD {head[:7]} -> {pub_last_analysis[:7]}')
    tags = {t: cmap.get(git(['rev-parse', t], SRC).strip(), '?') for t in git(['tag'], SRC).split()}
    (OUT.parent / (OUT.name + '_commit_map.tsv')).write_text('private\tpublic\tnote\n' + ''.join(f'{o}\t{n}\t{"first commit (specification)" if o == first else "last analysis commit" if o == head else ""}\n' for o, n in cmap.items()))

    # ---------------------------------------------------------------- 3. release files + final commit
    subst = {'{{FIRST_COMMIT}}': pub_first, '{{FIRST_COMMIT_DATE}}': first_date, '{{LAST_ANALYSIS_COMMIT}}': pub_last_analysis, '{{N_COMMITS}}': str(n_commits)}
    for name, dst in [('README.md', 'README.md'), ('LICENSE', 'LICENSE'), ('LICENSE-docs', 'LICENSE-docs'), ('CITATION.cff', 'CITATION.cff'), ('RELEASE_STEPS.md', 'RELEASE_STEPS.md'), ('gitignore', '.gitignore')]:
        txt = (PUB / name).read_text()
        for k, v in subst.items(): txt = txt.replace(k, v)
        (OUT / dst).write_text(txt)
    git(['add', '-A'], OUT)
    msg = ('Public release files: README, LICENSE (MIT) and LICENSE-docs (CC BY 4.0), CITATION.cff, .gitignore, RELEASE_STEPS.md\n\n'
           f'Generated by scripts/91_build_public_repo.py from the private repository at {head} (first commit {first} -> {pub_first}).\n\n' + TRAILER)
    git([*AUTHOR, 'commit', '--quiet', '-m', msg], OUT)
    pub_head = git(['rev-parse', 'HEAD'], OUT).strip()
    print(f'public HEAD {pub_head[:7]} on branch {git(["rev-parse", "--abbrev-ref", "HEAD"], OUT).strip()}; tags: ' + ', '.join(f'{t}={h[:7]}' for t, h in tags.items()))
    summary = dict(private_head=head, private_first=first, public_first=pub_first, public_last_analysis=pub_last_analysis, public_head=pub_head, n_commits=n_commits + 1, tags=tags, manifest=str(man_path))
    if a.no_check:
        print(json.dumps(summary, indent=1)); return

    # ---------------------------------------------------------------- 4. checks
    print('\n== check 1: private strings in the public tree ==')
    files = sorted(git(['ls-files'], OUT).splitlines()); hits = []
    for p in files:
        b = (OUT / p).read_bytes()
        try: txt = b.decode('utf-8'); binary = False
        except UnicodeDecodeError: txt = b.decode('latin-1'); binary = True
        for label, pat in CHECK_PATTERNS:
            for m in re.finditer(pat, txt):
                if label == 'email' and m.group(0) in ALLOWED_EMAILS: continue
                if binary and label in ('token', 'secret', 'api_key', 'prolific', 'worker'): continue
                ln = txt.count('\n', 0, m.start()) + 1; ctx = txt[max(0, m.start() - 40): m.end() + 40].replace('\n', ' ')
                hits.append((p, ln, label, 'binary' if binary else '', ctx)); break  # one hit per file per pattern
    for h in hits: print(f'  {h[0]}:{h[1]} [{h[2]}{" " + h[3] if h[3] else ""}] ...{h[4]}...')
    print(f'  {len(hits)} file x pattern hits')

    print('\n== check 2: sizes ==')
    sizes = {p: (OUT / p).stat().st_size for p in files}; total = sum(sizes.values()); big = {p: s for p, s in sizes.items() if s > MAX_FILE}
    print(f'  {len(files)} files, {total / 2**20:.1f} MB total (limit 100 MB) -> {"OK" if total < MAX_TOTAL else "TOO LARGE"}; files > 10 MB: {big if big else "none"}')
    print('  largest: ' + ', '.join(f'{p} {s / 2**20:.1f} MB' for p, s in sorted(sizes.items(), key=lambda x: -x[1])[:5]))

    print('\n== check 3: clone -> uv sync --frozen -> python -I scripts/88_paper_numbers.py -> diff; unit test ==')
    tmp = Path(tempfile.mkdtemp(prefix='public_repo_check_', dir=a.tmp)); clone = tmp / OUT.name
    git(['clone', '--quiet', str(OUT), str(clone)], tmp)
    env = {**os.environ, 'OMP_NUM_THREADS': '1'}
    r = subprocess.run(['uv', 'sync', '--frozen'], cwd=clone, text=True, capture_output=True, env=env)
    print(f'  uv sync --frozen: rc={r.returncode} ' + (r.stderr.strip().splitlines()[-1][:160] if r.stderr.strip() else ''))
    if r.returncode: print(r.stdout[-2000:], r.stderr[-2000:])
    r = subprocess.run(['uv', 'run', 'python', '-I', 'scripts/88_paper_numbers.py'], cwd=clone, text=True, capture_output=True, env=env)
    print(f'  scripts/88: rc={r.returncode}; ' + ' | '.join(l for l in r.stdout.splitlines() if l.startswith('[cached') or l.endswith('lines')))
    if r.returncode: print(r.stderr[-3000:])
    ref, new = (SRC / 'paper/numbers.md').read_text(), (clone / 'paper/numbers.md').read_text() if (clone / 'paper/numbers.md').exists() else ''
    same = ref == new; print(f'  numbers.md identical to the private copy: {same}')
    if not same:
        import difflib; print('\n'.join(list(difflib.unified_diff(ref.splitlines(), new.splitlines(), 'private', 'public', lineterm=''))[:60]))
    r = subprocess.run(['uv', 'run', 'python', 'scripts/tests/test_models_synthetic.py'], cwd=clone, text=True, capture_output=True, env=env)
    print(f'  scripts/tests/test_models_synthetic.py: rc={r.returncode} ' + (r.stdout.strip().splitlines()[-1][:160] if r.stdout.strip() else '') + (r.stderr.strip().splitlines()[-1][:160] if r.returncode and r.stderr.strip() else ''))
    st = git(['status', '--porcelain'], clone).strip()
    print('  git status in the test clone after running: ' + (st.replace("\n", "; ") if st else 'clean'))
    print(f'  test clone kept at {clone}')

    print('\n== check 4: git status of the output and history ==')
    st = git(['status', '--porcelain'], OUT).strip(); print('  git status: ' + ('clean' if not st else st))
    print('  ' + git(['log', '--oneline', '--reverse'], OUT).splitlines()[0] + '  ...  ' + git(['log', '--oneline', '-1'], OUT).strip())
    summary.update(check_hits=len(hits), total_mb=round(total / 2**20, 1), numbers_md_identical=same, test_clone=str(clone))
    print('\n' + json.dumps(summary, indent=1)); print(f'done in {time.time() - t0:.0f} s; manifest: {man_path}')


if __name__ == '__main__':
    main()
